static AcpV1Authentication authenticatedLocal() {
    AtomicBoolean authenticated = new AtomicBoolean(true);
    return new AcpV1Authentication() {
        @Override public List<Method> methods() {
            return List.of(new Method("local", "Local runtime", "Reconnect to this local runtime"));
        }
        @Override public boolean authenticated() { return authenticated.get(); }
        @Override public void authenticate(String methodId) {
            if (!"local".equals(methodId)) throw new IllegalArgumentException("unknown authentication method");
            authenticated.set(true);
        }
        @Override public void logout() { authenticated.set(false); }
    };
}
